def parse_json_values(data):
    decoder = json.JSONDecoder()
    idx = 0
    n = len(data)
    vals = []
    while idx < n:
        while idx < n and data[idx] in " \t\r\n":
            idx+=1
        if idx >= n:
            break
        try:
            val, end = decoder.raw_decode(data, idx)
            vals.append(val)
            idx = end
        except json.JSONDecodeError as e:
            raise e
    return vals

