def colorize(text, typ):
    if typ == "null":
        return COLOR_NULL + text + COLOR_RESET
    elif typ in ("bool","number"):
        return COLOR_FALSE_TRUE_NUM + text + COLOR_RESET
    elif typ == "string":
        return COLOR_STRING + text + COLOR_RESET
    elif typ == "field":
        return COLOR_FIELD + text + COLOR_RESET
    elif typ == "brace":
        return COLOR_BRACE + text + COLOR_RESET
    else:
        return text

def format_float_jq(f):
    if isinstance(f, int):
        return str(f)
    if f == 0.0:
        return "0"
    if isinstance(f, float) and f.is_integer():
        return str(int(f))
    s = repr(f)
    if 'e' in s:
        mant, exp = s.split('e')
        sign = exp[0]
        num = exp[1:].lstrip('0')
        if num == '':
            num = '0'
        s = f"{mant}E{sign}{num}"
    s = s.replace('e','E')
    return s

def json_dumps_compact(value, sort_keys=False, ascii_output=False, color=False):
    if value is None:
        s = "null"
        return colorize(s, "null") if color else s
    elif isinstance(value, bool):
        s = "true" if value else "false"
        return colorize(s, "bool") if color else s
    elif isinstance(value, int) and not isinstance(value, bool):
        s = str(value)
        return colorize(s, "number") if color else s
    elif isinstance(value, float):
        s = format_float_jq(value)
        return colorize(s, "number") if color else s
    elif isinstance(value, str):
        s = json.dumps(value, ensure_ascii=ascii_output)
        return colorize(s, "string") if color else s
    elif isinstance(value, list):
        if len(value) == 0:
            s = "[]"
            return colorize(s, "brace") if color else s
        if color:
            parts = []
            parts.append(COLOR_BRACE + "[" + COLOR_RESET)
            for idx, v in enumerate(value):
                if idx > 0:
                    parts.append(COLOR_BRACE + "," + COLOR_RESET)
                parts.append(json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=color))
            parts.append(COLOR_BRACE + "]" + COLOR_RESET)
            return "".join(parts)
        else:
            inner = ",".join(json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=False) for v in value)
            return "[" + inner + "]"
    elif isinstance(value, dict):
        if len(value) == 0:
            s = "{}"
            return colorize(s, "brace") if color else s
        items = list(value.items())
        if sort_keys:
            items.sort(key=lambda kv: kv[0])
        if color:
            parts = []
            parts.append(COLOR_BRACE + "{" + COLOR_RESET)
            first = True
            for k,v in items:
                if not first:
                    parts.append(COLOR_BRACE + "," + COLOR_RESET)
                first = False
                key_str = json.dumps(k, ensure_ascii=ascii_output)
                parts.append(COLOR_FIELD + key_str + COLOR_RESET)
                parts.append(COLOR_BRACE + ":" + COLOR_RESET)
                parts.append(json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=color))
            parts.append(COLOR_BRACE + "}" + COLOR_RESET)
            return "".join(parts)
        else:
            inner = ",".join(f"{json.dumps(k, ensure_ascii=ascii_output)}:{json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=False)}" for k,v in items)
            return "{" + inner + "}"
    else:
        return json.dumps(value, ensure_ascii=ascii_output)

def json_dumps_pretty(value, sort_keys=False, ascii_output=False, indent_spaces=2, use_tab=False, color=False, current_level=0):
    def indent_str(level):
        if use_tab:
            return "\t" * level
        else:
            return " " * (indent_spaces * level)
    if value is None:
        s = "null"
        return colorize(s, "null") if color else s
    elif isinstance(value, bool):
        s = "true" if value else "false"
        return colorize(s, "bool") if color else s
    elif isinstance(value, int) and not isinstance(value, bool):
        s = str(value)
        return colorize(s, "number") if color else s
    elif isinstance(value, float):
        s = format_float_jq(value)
        return colorize(s, "number") if color else s
    elif isinstance(value, str):
        s = json.dumps(value, ensure_ascii=ascii_output)
        return colorize(s, "string") if color else s
    elif isinstance(value, list):
        if len(value) == 0:
            s = "[]"
            return colorize(s, "brace") if color else s
        if color:
            parts = []
            parts.append(COLOR_BRACE + "[" + COLOR_RESET + "\n")
            for idx, v in enumerate(value):
                parts.append(indent_str(current_level+1))
                parts.append(json_dumps_pretty(v, sort_keys=sort_keys, ascii_output=ascii_output, indent_spaces=indent_spaces, use_tab=use_tab, color=color, current_level=current_level+1))
                if idx < len(value)-1:
                    parts.append(COLOR_BRACE + "," + COLOR_RESET + "\n")
                else:
                    parts.append("\n")
            parts.append(indent_str(current_level) + COLOR_BRACE + "]" + COLOR_RESET)
            return "".join(parts)
        else:
            parts = []
            parts.append("[\n")
            for idx, v in enumerate(value):
                parts.append(indent_str(current_level+1))
                parts.append(json_dumps_pretty(v, sort_keys=sort_keys, ascii_output=ascii_output, indent_spaces=indent_spaces, use_tab=use_tab, color=False, current_level=current_level+1))
                if idx < len(value)-1:
                    parts.append(",\n")
                else:
                    parts.append("\n")
            parts.append(indent_str(current_level) + "]")
            return "".join(parts)
    elif isinstance(value, dict):
        if len(value) == 0:
            s = "{}"
            return colorize(s, "brace") if color else s
        items = list(value.items())
        if sort_keys:
            items.sort(key=lambda kv: kv[0])
        if color:
            parts = []
            parts.append(COLOR_BRACE + "{" + COLOR_RESET + "\n")
            for idx, (k,v) in enumerate(items):
                parts.append(indent_str(current_level+1))
                key_str = json.dumps(k, ensure_ascii=ascii_output)
                parts.append(COLOR_FIELD + key_str + COLOR_RESET)
                parts.append(COLOR_BRACE + ":" + COLOR_RESET + " ")
                parts.append(json_dumps_pretty(v, sort_keys=sort_keys, ascii_output=ascii_output, indent_spaces=indent_spaces, use_tab=use_tab, color=color, current_level=current_level+1))
                if idx < len(items)-1:
                    parts.append(COLOR_BRACE + "," + COLOR_RESET + "\n")
                else:
                    parts.append("\n")
            parts.append(indent_str(current_level) + COLOR_BRACE + "}" + COLOR_RESET)
            return "".join(parts)
        else:
            parts = []
            parts.append("{\n")
            for idx, (k,v) in enumerate(items):
                parts.append(indent_str(current_level+1))
                key_str = json.dumps(k, ensure_ascii=ascii_output)
                parts.append(f"{key_str}: ")
                parts.append(json_dumps_pretty(v, sort_keys=sort_keys, ascii_output=ascii_output, indent_spaces=indent_spaces, use_tab=use_tab, color=False, current_level=current_level+1))
                if idx < len(items)-1:
                    parts.append(",\n")
                else:
                    parts.append("\n")
            parts.append(indent_str(current_level) + "}")
            return "".join(parts)
    else:
        return json.dumps(value, ensure_ascii=ascii_output)

# Tokenizer for filter
def tokenize(s):
    pos = 0
    tokens = []
    n = len(s)
    while pos < n:
        m = re.match(r'\s+', s[pos:])
        if m:
            pos += len(m.group(0))
            continue
        m = re.match(r'#.*', s[pos:])
        if m:
            pos += len(m.group(0))
            continue
        if s[pos] == '"':
            end = pos+1
            while end < n:
                if s[end] == '\\':
                    end+=2
                elif s[end] == '"':
                    end+=1
                    break
                else:
                    end+=1
            tokens.append(('STRING', s[pos:end], pos))
            pos = end
            continue
        m = re.match(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?', s[pos:])
        if m and m.group(0) not in ('','-'):
            # Avoid matching just '-'
            # Also need to ensure next char is not digit or letter that would be part of identifier? For now ok
            tokens.append(('NUMBER', m.group(0), pos))
            pos += len(m.group(0))
            continue
        if s[pos:pos+2] == '..':
            tokens.append(('DOTDOT', '..', pos))
            pos+=2
            continue
        if s[pos] == '.':
            tokens.append(('DOT', '.', pos))
            pos+=1
            continue
        if s[pos] == '$':
            tokens.append(('DOLLAR', '$', pos))
            pos+=1
            continue
        if s[pos] == '|':
            tokens.append(('PIPE', '|', pos))
            pos+=1
            continue
        if s[pos] == ',':
            tokens.append(('COMMA', ',', pos))
            pos+=1
            continue
        if s[pos] == ';':
            tokens.append(('SEMICOLON', ';', pos))
            pos+=1
            continue
        if s[pos] == ':':
            tokens.append(('COLON', ':', pos))
            pos+=1
            continue
        if s[pos] == '(':
            tokens.append(('LPAREN', '(', pos))
            pos+=1
            continue
        if s[pos] == ')':
            tokens.append(('RPAREN', ')', pos))
            pos+=1
            continue
        if s[pos] == '[':
            tokens.append(('LBRACKET', '[', pos))
            pos+=1
            continue
        if s[pos] == ']':
            tokens.append(('RBRACKET', ']', pos))
            pos+=1
            continue
        if s[pos] == '{':
            tokens.append(('LBRACE', '{', pos))
            pos+=1
            continue
        if s[pos] == '}':
            tokens.append(('RBRACE', '}', pos))
            pos+=1
            continue
        if s[pos] == '?':
            tokens.append(('QUESTION', '?', pos))
            pos+=1
            continue
        if s[pos:pos+2] in ('//','==','!=','<=','>='):
            tokens.append(('OP', s[pos:pos+2], pos))
            pos+=2
            continue
        if s[pos] in '<>=':
            tokens.append(('OP', s[pos], pos))
            pos+=1
            continue
        if s[pos] in '+-*/%':
            tokens.append(('OP', s[pos], pos))
            pos+=1
            continue
        m = re.match(r'[A-Za-z_][A-Za-z0-9_]*', s[pos:])
        if m:
            word = m.group(0)
            if word in ("and","or","not","if","then","elif","else","end","try","catch","def","as"):
                tokens.append((word.upper(), word, pos))
            else:
                tokens.append(('IDENT', word, pos))
            pos += len(word)
            continue
        tokens.append(('UNKNOWN', s[pos], pos))
        pos+=1
    return tokens

class ASTNode:
    pass

class Literal(ASTNode):
    def __init__(self, value):
        self.value = value

class Variable(ASTNode):
    def __init__(self, name):
        self.name = name

class Identity(ASTNode):
    pass

class FieldAccess(ASTNode):
    def __init__(self, base, field, is_optional=False):
        self.base = base
        self.field = field
        self.is_optional = is_optional

class IndexAccess(ASTNode):
    def __init__(self, base, index, is_optional=False):
        self.base = base
        self.index = index
        self.is_optional = is_optional

class SliceAccess(ASTNode):
    def __init__(self, base, start, end, is_optional=False):
        self.base = base
        self.start = start
        self.end = end
        self.is_optional = is_optional

class Iterate(ASTNode):
    def __init__(self, base, is_optional=False):
        self.base = base
        self.is_optional = is_optional

class Pipe(ASTNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class Comma(ASTNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class BinaryOp(ASTNode):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

class UnaryOp(ASTNode):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

class ArrayConstruct(ASTNode):
    def __init__(self, filter_inside=None):
        self.filter_inside = filter_inside

class ObjectConstruct(ASTNode):
    def __init__(self, pairs):
        self.pairs = pairs

class FuncCall(ASTNode):
    def __init__(self, name, args):
        self.name = name
        self.args = args

class IfNode(ASTNode):
    def __init__(self, cond, then_branch, elifs, else_branch):
        self.cond = cond
        self.then_branch = then_branch
        self.elifs = elifs
        self.else_branch = else_branch

class TryCatch(ASTNode):
    def __init__(self, try_branch, catch_branch):
        self.try_branch = try_branch
        self.catch_branch = catch_branch

class DefNode(ASTNode):
    def __init__(self, name, params, body, next_filter):
        self.name = name
        self.params = params
        self.body = body
        self.next_filter = next_filter

class Parser:
    def __init__(self, tokens, source):
        self.tokens = tokens
        self.pos = 0
        self.source = source

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None, None)

    def peek_type(self):
        t = self.peek()
        return t[0]

    def consume(self, expected_type=None):
        if self.pos >= len(self.tokens):
            return None
        tok = self.tokens[self.pos]
        if expected_type and tok[0] != expected_type:
            pass
        self.pos+=1
        return tok

    def get_line_col(self, idx):
        up_to = self.source[:idx]
        line = up_to.count('\n') + 1
        last_nl = up_to.rfind('\n')
        col = idx - last_nl if last_nl != -1 else idx+1
        return line, col

    def parse(self):
        if not self.tokens:
            raise SyntaxError("Top-level program not given (try \".\")")
        node = self.parse_filter()
        if self.pos < len(self.tokens):
            tok = self.tokens[self.pos]
            line, col = self.get_line_col(tok[2])
            raise SyntaxError(f"syntax error, unexpected '{tok[1]}', expecting end of file at <top-level>, line {line}, column {col}")
        return node

    def parse_filter(self):
        left = self.parse_pipe()
        while self.peek_type() == 'COMMA':
            self.consume('COMMA')
            right = self.parse_pipe()
            left = Comma(left, right)
        return left

    def parse_pipe(self):
        left = self.parse_or()
        while self.peek_type() == 'PIPE':
            self.consume('PIPE')
            right = self.parse_or()
            left = Pipe(left, right)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.peek_type() == 'OR':
            self.consume('OR')
            right = self.parse_and()
            left = BinaryOp('or', left, right)
        return left

    def parse_and(self):
        left = self.parse_alternative()
        while self.peek_type() == 'AND':
            self.consume('AND')
            right = self.parse_alternative()
            left = BinaryOp('and', left, right)
        return left

    def parse_alternative(self):
        left = self.parse_comparison()
        while self.peek_type() == 'OP' and self.peek()[1] == '//':
            self.consume('OP')
            right = self.parse_comparison()
            left = BinaryOp('//', left, right)
        return left

    def parse_comparison(self):
        left = self.parse_additive()
        while self.peek_type() == 'OP' and self.peek()[1] in ('==','!=','<','>','<=','>='):
            op = self.consume('OP')[1]
            right = self.parse_additive()
            left = BinaryOp(op, left, right)
        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.peek_type() == 'OP' and self.peek()[1] in ('+','-'):
            op = self.consume('OP')[1]
            right = self.parse_multiplicative()
            left = BinaryOp(op, left, right)
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.peek_type() == 'OP' and self.peek()[1] in ('*','/','%'):
            op = self.consume('OP')[1]
            right = self.parse_unary()
            left = BinaryOp(op, left, right)
        return left

    def parse_unary(self):
        if self.peek_type() == 'OP' and self.peek()[1] in ('+','-'):
            op = self.consume('OP')[1]
            operand = self.parse_unary()
            return UnaryOp(op, operand)
        if self.peek_type() == 'NOT':
            self.consume('NOT')
            operand = self.parse_unary()
            return UnaryOp('not', operand)
        return self.parse_suffix()

    def parse_suffix(self):
        base = self.parse_primary()
        while True:
            if self.peek_type() == 'DOT':
                self.consume('DOT')
                if self.peek_type() == 'IDENT':
                    field = self.consume('IDENT')[1]
                    is_opt = False
                    if self.peek_type() == 'QUESTION':
                        self.consume('QUESTION')
                        is_opt = True
                    base = FieldAccess(base, field, is_opt)
                    continue
                elif self.peek_type() == 'LBRACKET':
                    self.consume('LBRACKET')
                    if self.peek_type() == 'RBRACKET':
                        self.consume('RBRACKET')
                        is_opt = False
                        if self.peek_type() == 'QUESTION':
                            self.consume('QUESTION')
                            is_opt = True
                        base = Iterate(base, is_opt)
                        continue
                    else:
                        start_filter = None
                        end_filter = None
                        if self.peek_type() == 'COLON':
                            start_filter = None
                        else:
                            start_filter = self.parse_filter()
                        if self.peek_type() == 'COLON':
                            self.consume('COLON')
                            if self.peek_type() != 'RBRACKET':
                                end_filter = self.parse_filter()
                            self.consume('RBRACKET')
                            is_opt = False
                            if self.peek_type() == 'QUESTION':
                                self.consume('QUESTION')
                                is_opt = True
                            base = SliceAccess(base, start_filter, end_filter, is_opt)
                            continue
                        else:
                            self.consume('RBRACKET')
                            is_opt = False
                            if self.peek_type() == 'QUESTION':
                                self.consume('QUESTION')
                                is_opt = True
                            base = IndexAccess(base, start_filter, is_opt)
                            continue
                elif self.peek_type() == 'DOTDOT':
                    self.consume('DOTDOT')
                    base = FuncCall("recurse", [])
                    continue
                else:
                    is_opt = False
                    if self.peek_type() == 'QUESTION':
                        self.consume('QUESTION')
                        is_opt = True
                    continue
            else:
                break
        return base

    def parse_primary(self):
        tok_type = self.peek_type()
        if tok_type is None:
            return Identity()
        if tok_type == 'DOT':
            self.consume('DOT')
            if self.peek_type() == 'IDENT':
                field = self.consume('IDENT')[1]
                is_opt = False
                if self.peek_type() == 'QUESTION':
                    self.consume('QUESTION')
                    is_opt = True
                return FieldAccess(Identity(), field, is_opt)
            elif self.peek_type() == 'LBRACKET':
                self.consume('LBRACKET')
                if self.peek_type() == 'RBRACKET':
                    self.consume('RBRACKET')
                    is_opt = False
                    if self.peek_type() == 'QUESTION':
                        self.consume('QUESTION')
                        is_opt = True
                    return Iterate(Identity(), is_opt)
                else:
                    start_filter = None
                    end_filter = None
                    if self.peek_type() == 'COLON':
                        start_filter = None
                    else:
                        start_filter = self.parse_filter()
                    if self.peek_type() == 'COLON':
                        self.consume('COLON')
                        if self.peek_type() != 'RBRACKET':
                            end_filter = self.parse_filter()
                        self.consume('RBRACKET')
                        is_opt = False
                        if self.peek_type() == 'QUESTION':
                            self.consume('QUESTION')
                            is_opt = True
                        return SliceAccess(Identity(), start_filter, end_filter, is_opt)
                    else:
                        self.consume('RBRACKET')
                        is_opt = False
                        if self.peek_type() == 'QUESTION':
                            self.consume('QUESTION')
                            is_opt = True
                        return IndexAccess(Identity(), start_filter, is_opt)
            elif self.peek_type() == 'DOTDOT':
                self.consume('DOTDOT')
                return FuncCall("recurse", [])
            else:
                is_opt = False
                if self.peek_type() == 'QUESTION':
                    self.consume('QUESTION')
                    is_opt = True
                return Identity()
        elif tok_type == 'DOLLAR':
            self.consume('DOLLAR')
            if self.peek_type() == 'IDENT':
                name = self.consume('IDENT')[1]
                return Variable(name)
            else:
                raise SyntaxError("Expected variable name after $")
        elif tok_type == 'STRING':
            raw = self.consume('STRING')[1]
            try:
                val = json.loads(raw)
            except:
                val = raw[1:-1]
            return Literal(val)
        elif tok_type == 'NUMBER':
            raw = self.consume('NUMBER')[1]
            try:
                if '.' in raw or 'e' in raw.lower():
                    v = float(raw)
                else:
                    v = int(raw)
            except:
                v = float(raw)
            return Literal(v)
        elif tok_type == 'IDENT':
            ident = self.consume('IDENT')[1]
            if ident == 'null':
                return Literal(None)
            elif ident == 'true':
                return Literal(True)
            elif ident == 'false':
                return Literal(False)
            if self.peek_type() == 'LPAREN':
                self.consume('LPAREN')
                args = []
                if self.peek_type() != 'RPAREN':
                    while True:
                        arg_filter = self.parse_filter()
                        args.append(arg_filter)
                        if self.peek_type() == 'SEMICOLON':
                            self.consume('SEMICOLON')
                        else:
                            break
                self.consume('RPAREN')
                return FuncCall(ident, args)
            return FuncCall(ident, [])
        elif tok_type == 'LPAREN':
            self.consume('LPAREN')
            inner = self.parse_filter()
            self.consume('RPAREN')
            if self.peek_type() == 'QUESTION':
                self.consume('QUESTION')
            return inner
        elif tok_type == 'LBRACKET':
            self.consume('LBRACKET')
            if self.peek_type() == 'RBRACKET':
                self.consume('RBRACKET')
                return ArrayConstruct(None)
            else:
                inner = self.parse_filter()
                self.consume('RBRACKET')
                return ArrayConstruct(inner)
        elif tok_type == 'LBRACE':
            self.consume('LBRACE')
            pairs = []
            if self.peek_type() != 'RBRACE':
                while True:
                    if self.peek_type() == 'IDENT':
                        ident = self.consume('IDENT')[1]
                        if self.peek_type() == 'COLON':
                            self.consume('COLON')
                            val = self.parse_filter()
                            pairs.append((Literal(ident), val))
                        else:
                            pairs.append((Literal(ident), FieldAccess(Identity(), ident)))
                    elif self.peek_type() == 'STRING':
                        raw = self.consume('STRING')[1]
                        k = json.loads(raw)
                        self.consume('COLON')
                        v = self.parse_filter()
                        pairs.append((Literal(k), v))
                    elif self.peek_type() == 'LPAREN':
                        self.consume('LPAREN')
                        k_filter = self.parse_filter()
                        self.consume('RPAREN')
                        self.consume('COLON')
                        v_filter = self.parse_filter()
                        pairs.append((k_filter, v_filter))
                    elif self.peek_type() == 'DOLLAR':
                        self.consume('DOLLAR')
                        var_name = self.consume('IDENT')[1]
                        pairs.append((Literal(var_name), Variable(var_name)))
                    else:
                        raise SyntaxError(f"Unexpected token in object: {self.peek()}")
                    if self.peek_type() == 'COMMA':
                        self.consume('COMMA')
                        continue
                    else:
                        break
            self.consume('RBRACE')
            return ObjectConstruct(pairs)
        elif tok_type == 'IF':
            self.consume('IF')
            cond = self.parse_filter()
            self.consume('THEN')
            then_branch = self.parse_filter()
            elifs = []
            while self.peek_type() == 'ELIF':
                self.consume('ELIF')
                elif_cond = self.parse_filter()
                self.consume('THEN')
                elif_branch = self.parse_filter()
                elifs.append((elif_cond, elif_branch))
            else_branch = None
            if self.peek_type() == 'ELSE':
                self.consume('ELSE')
                else_branch = self.parse_filter()
            self.consume('END')
            return IfNode(cond, then_branch, elifs, else_branch)
        elif tok_type == 'TRY':
            self.consume('TRY')
            try_branch = self.parse_filter()
            catch_branch = None
            if self.peek_type() == 'CATCH':
                self.consume('CATCH')
                catch_branch = self.parse_filter()
            return TryCatch(try_branch, catch_branch)
        elif tok_type == 'DEF':
            self.consume('DEF')
            fname = self.consume('IDENT')[1]
            params = []
            if self.peek_type() == 'LPAREN':
                self.consume('LPAREN')
                while self.peek_type() != 'RPAREN':
                    if self.peek_type() == 'IDENT':
                        params.append(self.consume('IDENT')[1])
                    elif self.peek_type() == 'DOLLAR':
                        self.consume('DOLLAR')
                        params.append(self.consume('IDENT')[1])
                    else:
                        raise SyntaxError("Expected param")
                    if self.peek_type() == 'SEMICOLON':
                        self.consume('SEMICOLON')
                    else:
                        break
                self.consume('RPAREN')
            self.consume('COLON')
            body = self.parse_filter()
            self.consume('SEMICOLON')
            next_filter = self.parse_filter()
            return DefNode(fname, params, body, next_filter)
        else:
            raise SyntaxError(f"Unexpected token {tok_type} {self.peek()}")

class JQContext:
    def __init__(self):
        self.vars = {}
        self.funcs = {}

    def copy(self):
        ctx = JQContext()
        ctx.vars = dict(self.vars)
        ctx.funcs = dict(self.funcs)
        return ctx

def apply_binary_op(op, left, right):
    if op == '+':
        if isinstance(left, (int,float)) and isinstance(right, (int,float)):
            return left + right
        elif isinstance(left, str) and isinstance(right, str):
            return left + right
        elif isinstance(left, list) and isinstance(right, list):
            return left + right
        elif isinstance(left, dict) and isinstance(right, dict):
            res = dict(left)
            res.update(right)
            return res
        elif left is None:
            return right
        elif right is None:
            return left
        else:
            raise Exception(f"Cannot add")
    elif op == '-':
        if isinstance(left, (int,float)) and isinstance(right, (int,float)):
            return left - right
        elif isinstance(left, list) and isinstance(right, list):
            return [x for x in left if x not in right]
        else:
            raise Exception("Cannot subtract")
    elif op == '*':
        if isinstance(left, (int,float)) and isinstance(right, (int,float)):
            return left * right
        elif isinstance(left, str) and isinstance(right, int):
            return left * right
        elif isinstance(left, int) and isinstance(right, str):
            return left * right
        else:
            raise Exception("Cannot multiply")
    elif op == '/':
        if isinstance(left, (int,float)) and isinstance(right, (int,float)):
            if right == 0:
                raise Exception("number (1) and number (0) cannot be divided because the divisor is zero")
            return left / right
        elif isinstance(left, str) and isinstance(right, str):
            return left.split(right)
        else:
            raise Exception("Cannot divide")
    elif op == '%':
        if isinstance(left, (int,float)) and isinstance(right, (int,float)):
            if right == 0:
                raise Exception("Division by zero")
            return left % right
        else:
            raise Exception("Cannot mod")
    elif op == '==':
        return left == right
    elif op == '!=':
        return left != right
    elif op == '<':
        try:
            return left < right
        except:
            return False
    elif op == '>':
        try:
            return left > right
        except:
            return False
    elif op == '<=':
        try:
            return left <= right
        except:
            return False
    elif op == '>=':
        try:
            return left >= right
        except:
            return False
    elif op == '//':
        if left is not None:
            return left
        else:
            return right
    else:
        raise Exception(f"Unknown op {op}")

def eval_filter(node, input_val, ctx):
    if isinstance(node, Literal):
        yield node.value
    elif isinstance(node, Variable):
        if node.name in ctx.vars:
            yield ctx.vars[node.name]
        else:
            raise Exception(f"${node.name} is not defined")
    elif isinstance(node, Identity):
        yield input_val
    elif isinstance(node, FieldAccess):
        for base_val in eval_filter(node.base, input_val, ctx):
            try:
                if isinstance(base_val, dict):
                    if node.field in base_val:
                        yield base_val[node.field]
                    else:
                        yield None
                else:
                    if node.is_optional:
                        continue
                    else:
                        raise Exception(f"Cannot index {type(base_val).__name__} with string \"{node.field}\"")
            except Exception as e:
                if node.is_optional:
                    continue
                else:
                    raise e
    elif isinstance(node, IndexAccess):
        for base_val in eval_filter(node.base, input_val, ctx):
            idx_vals = list(eval_filter(node.index, input_val, ctx))
            if not idx_vals:
                continue
            idx_val = idx_vals[0]
            try:
                if isinstance(base_val, list):
                    if isinstance(idx_val, int):
                        if idx_val < 0:
                            idx_val = len(base_val) + idx_val
                        if 0 <= idx_val < len(base_val):
                            yield base_val[idx_val]
                        else:
                            yield None
                    else:
                        raise Exception("Cannot index array")
                elif isinstance(base_val, dict):
                    if isinstance(idx_val, str):
                        yield base_val.get(idx_val)
                    else:
                        raise Exception("Cannot index object")
                elif isinstance(base_val, str):
                    if isinstance(idx_val, int):
                        if idx_val < 0:
                            idx_val = len(base_val) + idx_val
                        if 0 <= idx_val < len(base_val):
                            yield base_val[idx_val]
                        else:
                            yield None
                    else:
                        raise Exception("Cannot index string")
                else:
                    if node.is_optional:
                        continue
                    else:
                        raise Exception("Cannot index")
            except Exception as e:
                if node.is_optional:
                    continue
                else:
                    raise e
    elif isinstance(node, SliceAccess):
        for base_val in eval_filter(node.base, input_val, ctx):
            start_val = None
            end_val = None
            if node.start is not None:
                s_vals = list(eval_filter(node.start, input_val, ctx))
                if s_vals:
                    start_val = s_vals[0]
            if node.end is not None:
                e_vals = list(eval_filter(node.end, input_val, ctx))
                if e_vals:
                    end_val = e_vals[0]
            try:
                if isinstance(base_val, list):
                    s = start_val if isinstance(start_val, int) else 0
                    e = end_val if isinstance(end_val, int) else len(base_val)
                    if s < 0:
                        s = max(0, len(base_val)+s)
                    if e < 0:
                        e = max(0, len(base_val)+e)
                    yield base_val[s:e]
                elif isinstance(base_val, str):
                    s = start_val if isinstance(start_val, int) else 0
                    e = end_val if isinstance(end_val, int) else len(base_val)
                    if s < 0:
                        s = max(0, len(base_val)+s)
                    if e < 0:
                        e = max(0, len(base_val)+e)
                    yield base_val[s:e]
                else:
                    if node.is_optional:
                        continue
                    else:
                        raise Exception("Cannot slice")
            except Exception as e:
                if node.is_optional:
                    continue
                else:
                    raise e
    elif isinstance(node, Iterate):
        for base_val in eval_filter(node.base, input_val, ctx):
            try:
                if isinstance(base_val, list):
                    for item in base_val:
                        yield item
                elif isinstance(base_val, dict):
                    for v in base_val.values():
                        yield v
                else:
                    if node.is_optional:
                        continue
                    else:
                        raise Exception("Cannot iterate")
            except Exception as e:
                if node.is_optional:
                    continue
                else:
                    raise e
    elif isinstance(node, Pipe):
        for left_out in eval_filter(node.left, input_val, ctx):
            yield from eval_filter(node.right, left_out, ctx)
    elif isinstance(node, Comma):
        yield from eval_filter(node.left, input_val, ctx)
        yield from eval_filter(node.right, input_val, ctx)
    elif isinstance(node, BinaryOp):
        if node.op == 'and':
            for l in eval_filter(node.left, input_val, ctx):
                def is_truthy(v):
                    return not (v is False or v is None)
                if not is_truthy(l):
                    yield l
                else:
                    for r in eval_filter(node.right, input_val, ctx):
                        yield r
            return
        elif node.op == 'or':
            for l in eval_filter(node.left, input_val, ctx):
                def is_truthy(v):
                    return not (v is False or v is None)
                if is_truthy(l):
                    yield l
                else:
                    for r in eval_filter(node.right, input_val, ctx):
                        yield r
            return
        left_vals = list(eval_filter(node.left, input_val, ctx))
        right_vals = list(eval_filter(node.right, input_val, ctx))
        for lv in left_vals:
            for rv in right_vals:
                try:
                    res = apply_binary_op(node.op, lv, rv)
                    yield res
                except Exception as e:
                    raise e
    elif isinstance(node, UnaryOp):
        for v in eval_filter(node.operand, input_val, ctx):
            if node.op == '-':
                if isinstance(v, (int,float)):
                    yield -v
                else:
                    raise Exception("Cannot apply unary -")
            elif node.op == '+':
                yield v
            elif node.op == 'not':
                if v is False or v is None:
                    yield True
                else:
                    yield False
    elif isinstance(node, ArrayConstruct):
        if node.filter_inside is None:
            yield []
        else:
            vals = list(eval_filter(node.filter_inside, input_val, ctx))
            yield vals
    elif isinstance(node, ObjectConstruct):
        obj = {}
        for k_node, v_node in node.pairs:
            k_vals = list(eval_filter(k_node, input_val, ctx))
            v_vals = list(eval_filter(v_node, input_val, ctx))
            if not k_vals or not v_vals:
                continue
            k = k_vals[0]
            v = v_vals[0]
            if not isinstance(k, str):
                k = str(k)
            obj[k] = v
        yield obj
    elif isinstance(node, FuncCall):
        evaluated_args = []
        for arg_node in node.args:
            vals = list(eval_filter(arg_node, input_val, ctx))
            evaluated_args.append(vals[0] if vals else None)
        if node.name in ctx.funcs:
            params, body = ctx.funcs[node.name]
            new_ctx = ctx.copy()
            for p_name, arg_val in zip(params, evaluated_args):
                new_ctx.vars[p_name] = arg_val
            yield from eval_filter(body, input_val, new_ctx)
        else:
            # builtin handling
            try:
                if node.name == "keys":
                    if isinstance(input_val, dict):
                        yield sorted(input_val.keys())
                    else:
                        raise Exception("Cannot get keys")
                elif node.name == "keys_unsorted":
                    if isinstance(input_val, dict):
                        yield list(input_val.keys())
                    else:
                        raise Exception("Cannot get keys_unsorted")
                elif node.name == "values":
                    if isinstance(input_val, dict):
                        yield list(input_val.values())
                    elif isinstance(input_val, list):
                        yield list(input_val)
                    else:
                        raise Exception("Cannot get values")
                elif node.name == "length":
                    if isinstance(input_val, (list, dict, str)):
                        yield len(input_val)
                    elif input_val is None:
                        yield 0
                    else:
                        raise Exception("Cannot get length")
                elif node.name == "type":
                    if input_val is None:
                        yield "null"
                    elif isinstance(input_val, bool):
                        yield "boolean"
                    elif isinstance(input_val, int) and not isinstance(input_val, bool):
                        yield "number"
                    elif isinstance(input_val, float):
                        yield "number"
                    elif isinstance(input_val, str):
                        yield "string"
                    elif isinstance(input_val, list):
                        yield "array"
                    elif isinstance(input_val, dict):
                        yield "object"
                    else:
                        yield "unknown"
                elif node.name == "add":
                    if isinstance(input_val, list):
                        if len(input_val) == 0:
                            yield None
                        else:
                            res = input_val[0]
                            for el in input_val[1:]:
                                res = apply_binary_op('+', res, el)
                            yield res
                    else:
                        raise Exception("add")
                elif node.name == "map":
                    if isinstance(input_val, list):
                        if not node.args:
                            raise Exception("map requires filter")
                        map_filter = node.args[0]
                        result = []
                        for el in input_val:
                            for out in eval_filter(map_filter, el, ctx):
                                result.append(out)
                        yield result
                    else:
                        raise Exception("map")
                elif node.name == "select":
                    if not node.args:
                        raise Exception("select")
                    cond_filter = node.args[0]
                    cond_vals = list(eval_filter(cond_filter, input_val, ctx))
                    for cv in cond_vals:
                        if cv is not False and cv is not None:
                            yield input_val
                            break
                elif node.name == "empty":
                    return
                elif node.name == "not":
                    if input_val is False or input_val is None:
                        yield True
                    else:
                        yield False
                elif node.name == "tostring":
                    if isinstance(input_val, str):
                        yield input_val
                    else:
                        if isinstance(input_val, (dict,list)):
                            yield json.dumps(input_val)
                        else:
                            yield str(input_val)
                elif node.name == "tonumber":
                    if isinstance(input_val, (int,float)):
                        yield input_val
                    elif isinstance(input_val, str):
                        try:
                            if '.' in input_val or 'e' in input_val.lower():
                                yield float(input_val)
                            else:
                                yield int(input_val)
                        except:
                            raise Exception("tonumber")
                    else:
                        raise Exception("tonumber")
                elif node.name == "tojson":
                    yield json.dumps(input_val, ensure_ascii=False)
                elif node.name == "fromjson":
                    if isinstance(input_val, str):
                        yield json.loads(input_val)
                    else:
                        raise Exception("fromjson")
                elif node.name == "split":
                    if isinstance(input_val, str):
                        sep = evaluated_args[0] if evaluated_args else ""
                        yield input_val.split(sep)
                    else:
                        raise Exception("split")
                elif node.name == "join":
                    if isinstance(input_val, list):
                        sep = evaluated_args[0] if evaluated_args else ""
                        yield sep.join(str(x) for x in input_val)
                    else:
                        raise Exception("join")
                elif node.name == "contains":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        yield evaluated_args[0] in input_val
                    elif isinstance(input_val, list):
                        yield evaluated_args[0] in input_val
                    else:
                        yield False
                elif node.name == "startswith":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        yield input_val.startswith(evaluated_args[0])
                    else:
                        yield False
                elif node.name == "endswith":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        yield input_val.endswith(evaluated_args[0])
                    else:
                        yield False
                elif node.name == "ltrimstr":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        s = evaluated_args[0]
                        if input_val.startswith(s):
                            yield input_val[len(s):]
                        else:
                            yield input_val
                    else:
                        raise Exception("ltrimstr")
                elif node.name == "rtrimstr":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        s = evaluated_args[0]
                        if input_val.endswith(s):
                            yield input_val[:-len(s)] if s != "" else input_val
                        else:
                            yield input_val
                    else:
                        raise Exception("rtrimstr")
                elif node.name == "sort":
                    if isinstance(input_val, list):
                        try:
                            yield sorted(input_val)
                        except:
                            yield sorted(input_val, key=lambda x: str(x))
                    else:
                        raise Exception("sort")
                elif node.name == "unique":
                    if isinstance(input_val, list):
                        try:
                            yield sorted(set(input_val))
                        except:
                            # preserve order and unique
                            seen = []
                            for x in input_val:
                                if x not in seen:
                                    seen.append(x)
                            yield seen
                    else:
                        raise Exception("unique")
                elif node.name == "reverse":
                    if isinstance(input_val, list):
                        yield list(reversed(input_val))
                    else:
                        raise Exception("reverse")
                elif node.name == "flatten":
                    if isinstance(input_val, list):
                        depth = evaluated_args[0] if evaluated_args else None
                        def flatten(arr, d):
                            res = []
                            for el in arr:
                                if isinstance(el, list) and (d is None or d>0):
                                    nd = None if d is None else d-1
                                    res.extend(flatten(el, nd))
                                else:
                                    res.append(el)
                            return res
                        yield flatten(input_val, depth)
                    else:
                        raise Exception("flatten")
                elif node.name == "any":
                    if isinstance(input_val, list):
                        yield any(el is not False and el is not None for el in input_val)
                    else:
                        raise Exception("any")
                elif node.name == "all":
                    if isinstance(input_val, list):
                        yield all(el is not False and el is not None for el in input_val)
                    else:
                        raise Exception("all")
                elif node.name == "first":
                    if isinstance(input_val, list):
                        if len(input_val)>0:
                            yield input_val[0]
                elif node.name == "last":
                    if isinstance(input_val, list):
                        if len(input_val)>0:
                            yield input_val[-1]
                elif node.name == "nth":
                    n = evaluated_args[0] if evaluated_args else 0
                    if isinstance(input_val, list):
                        if 0 <= n < len(input_val):
                            yield input_val[n]
                        elif n < 0 and -len(input_val) <= n:
                            yield input_val[n]
                elif node.name == "limit":
                    if len(node.args) >= 2:
                        n_filter = node.args[0]
                        inner_filter = node.args[1]
                        n_vals = list(eval_filter(n_filter, input_val, ctx))
                        n_val = n_vals[0] if n_vals else 0
                        count = 0
                        for out in eval_filter(inner_filter, input_val, ctx):
                            if count < n_val:
                                yield out
                                count+=1
                            else:
                                break
                elif node.name == "range":
                    if len(evaluated_args) == 1:
                        end = evaluated_args[0]
                        if isinstance(end, int):
                            for i in range(end):
                                yield i
                    elif len(evaluated_args) == 2:
                        start, end = evaluated_args
                        if isinstance(start,int) and isinstance(end,int):
                            for i in range(start,end):
                                yield i
                    elif len(evaluated_args) == 3:
                        start,end,step = evaluated_args
                        if isinstance(start,int) and isinstance(end,int) and isinstance(step,int):
                            for i in range(start,end,step):
                                yield i
                elif node.name == "recurse":
                    def recurse(val):
                        yield val
                        if isinstance(val, dict):
                            for v in val.values():
                                yield from recurse(v)
                        elif isinstance(val, list):
                            for v in val:
                                yield from recurse(v)
                    yield from recurse(input_val)
                elif node.name == "error":
                    msg = evaluated_args[0] if evaluated_args else ""
                    raise Exception(msg)
                elif node.name == "inputs":
                    remaining = ctx.vars.get("_inputs_remaining", [])
                    idx = ctx.vars.get("_inputs_index", 0)
                    if idx < len(remaining):
                        ctx.vars["_inputs_index"] = idx+1
                        yield remaining[idx]
                    else:
                        return
                elif node.name == "input":
                    remaining = ctx.vars.get("_inputs_remaining", [])
                    idx = ctx.vars.get("_inputs_index", 0)
                    if idx < len(remaining):
                        ctx.vars["_inputs_index"] = idx+1
                        yield remaining[idx]
                    else:
                        return
                elif node.name == "path":
                    # path(filter) => output path to value that satisfies filter?
                    # Simplified: if arg is field access, return path
                    # We won't fully implement
                    yield []
                else:
                    raise Exception(f"{node.name}/0 is not defined")
            except Exception as e:
                raise e
    elif isinstance(node, IfNode):
        cond_vals = list(eval_filter(node.cond, input_val, ctx))
        cond_val = cond_vals[0] if cond_vals else None
        def is_truthy(v):
            return v is not False and v is not None
        if is_truthy(cond_val):
            yield from eval_filter(node.then_branch, input_val, ctx)
        else:
            matched = False
            for elif_cond, elif_branch in node.elifs:
                ec_vals = list(eval_filter(elif_cond, input_val, ctx))
                ec_val = ec_vals[0] if ec_vals else None
                if is_truthy(ec_val):
                    yield from eval_filter(elif_branch, input_val, ctx)
                    matched = True
                    break
            if not matched:
                if node.else_branch is not None:
                    yield from eval_filter(node.else_branch, input_val, ctx)
    elif isinstance(node, TryCatch):
        try:
            yield from eval_filter(node.try_branch, input_val, ctx)
        except Exception as e:
            if node.catch_branch is not None:
                yield from eval_filter(node.catch_branch, str(e), ctx)
            else:
                yield None
    elif isinstance(node, DefNode):
        new_ctx = ctx.copy()
        new_ctx.funcs[node.name] = (node.params, node.body)
        yield from eval_filter(node.next_filter, input_val, new_ctx)
    else:
        raise Exception(f"Unsupported node {type(node)}")

def main():
    argv = sys.argv[1:]
    opts, positional = parse_cli_v2(argv)
    filter_str, input_files, mode_positional = determine_filter_and_files(opts, positional)

    named_vars = {}
    for name, val in opts["arg_vars"]:
        if name not in named_vars:
            named_vars[name] = val
    for name, val in opts["argjson_vars"]:
        if name not in named_vars:
            try:
                parsed = json.loads(val)
            except:
                exit_error(f"jq: invalid JSON text passed to --argjson\n{HELP_FOOTER}",2)
            named_vars[name] = parsed
    for name, fname in opts["slurpfile_vars"]:
        if name not in named_vars:
            try:
                with open(fname, 'r', encoding='utf-8') as f:
                    data = f.read()
                    vals = parse_json_values(data)
                    named_vars[name] = vals
            except FileNotFoundError:
                exit_error(f"jq: Bad JSON in --slurpfile {name} {fname}: Could not open {fname}: No such file or directory\n",2)
            except Exception as e:
                exit_error(f"jq: Bad JSON in --slurpfile {name} {fname}: {e}\n",2)
    for name, fname in opts["rawfile_vars"]:
        if name not in named_vars:
            try:
                with open(fname, 'r', encoding='utf-8') as f:
                    data = f.read()
                    named_vars[name] = data
            except FileNotFoundError:
                exit_error(f"jq: Bad JSON in --rawfile {name} {fname}: Could not open {fname}: No such file or directory\n",2)

    positional_args = []
    if opts["args_mode"] == "args":
        positional_args = mode_positional
    elif opts["args_mode"] == "jsonargs":
        for p in mode_positional:
            try:
                parsed = json.loads(p)
                positional_args.append(parsed)
            except:
                exit_error(f"jq: invalid JSON text passed to --jsonargs\n{HELP_FOOTER}",2)

    args_obj = {
        "positional": positional_args,
        "named": named_vars
    }

    ctx = JQContext()
    ctx.vars.update(named_vars)
    ctx.vars["ARGS"] = args_obj

    # Read inputs
    # Handle library path for include: we will attempt to detect include and error if not found
    if "include" in filter_str or "import" in filter_str:
        # Very naive check for module not found
        # Look for include "xxx" pattern
        import re
        m = re.search(r'include\s+"([^"]+)"', filter_str)
        if m:
            mod = m.group(1)
            found = False
            for lp in opts["library_paths"]:
                # check <lp>/<mod>.jq and <lp>/<mod>/...?
                p1 = os.path.join(lp, mod + ".jq")
                p2 = os.path.join(lp, mod)
                if os.path.isfile(p1) or os.path.isfile(p2):
                    found = True
                    break
            if not found:
                eprint(f"jq: error: module not found: {mod}\n\njq: 1 compile error\n")
                sys.exit(3)

    def read_all_remaining():
        tmp_opts = dict(opts)
        tmp_opts["null_input"] = False
        try:
            return read_inputs(tmp_opts, input_files)
        except Exception as e:
            # e may contain vals
            # parse error handling
            msg = str(e)
            if "parse error" in msg:
                # need to extract vals?
                # For simplicity, exit 5
                eprint(f"jq: {msg}\n")
                sys.exit(5)
            else:
                # re-raise?
                return []

    # Main inputs
    try:
        main_inputs = read_inputs(opts, input_files)
    except Exception as e:
        # If exception contains vals, we need to output vals before error?
        # Our read_inputs currently raises with message containing vals
        # For simplicity, if parse error, we will attempt to parse what we can and output?
        # For now, handle parse error: print error and exit 5
        # But we need to also output any valid values before error? The original binary does: it outputs valid json before parse error, then error line
        # Our read_inputs that uses parse_json_values will succeed for valid part and then raise on invalid, but we have all_vals before error? In our implementation, parse_json_values raises on error, all_vals already collected before? Actually in read_inputs we catch and raise with vals? Let's handle.

        # Extract vals from message if present
        # For now, just print parse error and exit 5
        if "parse error" in str(e):
            # Try to extract line col?
            # Use original error
            # For simplicity, produce generic
            eprint(f"jq: {e}\n")
            sys.exit(5)
        else:
            # maybe contains vals list in message "with vals [...]"
            # We need to parse
            # For now exit
            eprint(f"jq: {e}\n")
            sys.exit(5)

    # Handle null_input case: remaining inputs for inputs builtin
    if opts["null_input"]:
        try:
            remaining_inputs = read_all_remaining()
        except:
            remaining_inputs = []
        ctx.vars["_inputs_remaining"] = remaining_inputs
        ctx.vars["_inputs_index"] = 0
    else:
        # For each main input we will set remaining as slice
        pass

    # Parse filter
    try:
        tokens = tokenize(filter_str)
        parser = Parser(tokens, filter_str)
        ast_root = parser.parse()
    except SyntaxError as se:
        msg = str(se)
        if "Top-level" in msg:
            eprint(f"jq: error: {msg}\njq: 1 compile error\n")
