    elif typ in ("bool","number"):
        return COLOR_FALSE_TRUE_NUM + text + COLOR_RESET
    elif typ == "string":
        return COLOR_STRING + text + COLOR_RESET
    elif typ == "field":
        return COLOR_FIELD + text + COLOR_RESET
    elif typ == "brace":
        return COLOR_BRACE + text + COLOR_RESET
    else:
        return text

def format_float_jq(f):
    if isinstance(f, int):
        return str(f)
    if f == 0.0:
        return "0"
    if isinstance(f, float) and f.is_integer():
        return str(int(f))
    s = repr(f)
    if 'e' in s:
        mant, exp = s.split('e')
        sign = exp[0]
        num = exp[1:].lstrip('0')
        if num == '':
            num = '0'
        s = f"{mant}E{sign}{num}"
    s = s.replace('e','E')
    return s

def json_dumps_compact(value, sort_keys=False, ascii_output=False, color=False):
    if value is None:
        s = "null"
        return colorize(s, "null") if color else s
    elif isinstance(value, bool):
        s = "true" if value else "false"
        return colorize(s, "bool") if color else s
    elif isinstance(value, int) and not isinstance(value, bool):
        s = str(value)
        return colorize(s, "number") if color else s
    elif isinstance(value, float):
        s = format_float_jq(value)
