    elif isinstance(value, list):
        if len(value) == 0:
            s = "[]"
            return colorize(s, "brace") if color else s
        if color:
            parts = []
            parts.append(COLOR_BRACE + "[" + COLOR_RESET)
            for idx, v in enumerate(value):
                if idx > 0:
                    parts.append(COLOR_BRACE + "," + COLOR_RESET)
                parts.append(json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=color))
            parts.append(COLOR_BRACE + "]" + COLOR_RESET)
            return "".join(parts)
        else:
            inner = ",".join(json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=False) for v in value)
            return "[" + inner + "]"
    elif isinstance(value, dict):
        if len(value) == 0:
            s = "{}"
            return colorize(s, "brace") if color else s
        items = list(value.items())
        if sort_keys:
            items.sort(key=lambda kv: kv[0])
        if color:
            parts = []
            parts.append(COLOR_BRACE + "{" + COLOR_RESET)
            first = True
            for k,v in items:
                if not first:
                    parts.append(COLOR_BRACE + "," + COLOR_RESET)
                first = False
                key_str = json.dumps(k, ensure_ascii=ascii_output)
                parts.append(COLOR_FIELD + key_str + COLOR_RESET)
                parts.append(COLOR_BRACE + ":" + COLOR_RESET)
                parts.append(json_dumps_compact(v, sort_keys=sort_keys, ascii_output=ascii_output, color=color))
