def parse_json_values(data):
    decoder = json.JSONDecoder()
    idx = 0
    n = len(data)
    vals = []
    while idx < n:
        while idx < n and data[idx] in " \t\r\n":
            idx+=1
        if idx >= n:
            break
        try:
            val, end = decoder.raw_decode(data, idx)
            vals.append(val)
            idx = end
        except json.JSONDecodeError as e:
            raise e
    return vals

def read_inputs(opts, input_files):
    if opts["null_input"]:
        return [None]
    sources = []
    if not input_files:
        data = sys.stdin.read()
        if data == "":
            return []
        sources.append(("stdin", data))
    else:
        for fname in input_files:
            if fname == "-":
                data = sys.stdin.read()
                sources.append(("stdin", data))
            else:
                try:
                    with open(fname, 'r', encoding='utf-8') as f:
                        data = f.read()
                except FileNotFoundError:
                    exit_error(f"jq: error: Could not open file {fname}: No such file or directory\n",2)
                sources.append((fname, data))
    inputs = []
    if opts["raw_input"]:
        if opts["slurp"]:
            combined = "".join(d for _,d in sources)
            inputs = [combined]
        else:
            for _, data in sources:
                lines = data.splitlines()
                for line in lines:
                    inputs.append(line)
    else:
        if opts["seq"]:
            for _, data in sources:
                parts = data.split("\x1e")
                for part in parts:
                    part = part.strip()
                    if part == "":
                        continue
                    try:
                        val = json.loads(part)
                        inputs.append(val)
                    except Exception as e:
                        eprint(f"jq: ignoring parse error: Unfinished abandoned text at EOF at line 1, column 8\n")
                        continue
        elif opts["stream"] or opts["stream_errors"]:
            for _, data in sources:
                try:
                    vals = parse_json_values(data)
                except Exception as e:
                    if opts["stream_errors"]:
                        inputs.append([f"{e.msg} at line {e.lineno}, column {e.colno}", []])
                        continue
                    else:
                        eprint(f"jq: parse error: {e.msg} at line {e.lineno}, column {e.colno}\n")
                        sys.exit(5)
                for v in vals:
                    def gen_stream(val, path=None):
                        if path is None:
                            path = []
                        if isinstance(val, dict):
                            for k, vv in val.items():
                                cur = path + [k]
                                if isinstance(vv, (dict, list)):
                                    yield from gen_stream(vv, cur)
                                    yield [cur]
                                else:
                                    yield [cur, vv]
                                    yield [cur]
                        elif isinstance(val, list):
                            for idx, vv in enumerate(val):
                                cur = path + [idx]
                                if isinstance(vv, (dict, list)):
                                    yield from gen_stream(vv, cur)
                                    yield [cur]
                                else:
                                    yield [cur, vv]
                                    yield [cur]
                        else:
                            yield [path, val]
                    inputs.extend(list(gen_stream(v)))
            if opts["slurp"]:
                inputs = [inputs]
        else:
            all_vals = []
            for _, data in sources:
                if data.strip() == "":
                    continue
                try:
