        for left_out in eval_filter(node.left, input_val, ctx):
            yield from eval_filter(node.right, left_out, ctx)
    elif isinstance(node, Comma):
        yield from eval_filter(node.left, input_val, ctx)
        yield from eval_filter(node.right, input_val, ctx)
    elif isinstance(node, BinaryOp):
        if node.op == 'and':
            for l in eval_filter(node.left, input_val, ctx):
                def is_truthy(v):
                    return not (v is False or v is None)
                if not is_truthy(l):
                    yield l
                else:
                    for r in eval_filter(node.right, input_val, ctx):
                        yield r
            return
        elif node.op == 'or':
            for l in eval_filter(node.left, input_val, ctx):
                def is_truthy(v):
                    return not (v is False or v is None)
                if is_truthy(l):
                    yield l
                else:
                    for r in eval_filter(node.right, input_val, ctx):
                        yield r
            return
        left_vals = list(eval_filter(node.left, input_val, ctx))
        right_vals = list(eval_filter(node.right, input_val, ctx))
        for lv in left_vals:
            for rv in right_vals:
                try:
                    res = apply_binary_op(node.op, lv, rv)
                    yield res
