                    elif isinstance(input_val, int) and not isinstance(input_val, bool):
                        yield "number"
                    elif isinstance(input_val, float):
                        yield "number"
                    elif isinstance(input_val, str):
                        yield "string"
                    elif isinstance(input_val, list):
                        yield "array"
                    elif isinstance(input_val, dict):
                        yield "object"
                    else:
                        yield "unknown"
                elif node.name == "add":
                    if isinstance(input_val, list):
                        if len(input_val) == 0:
                            yield None
                        else:
