                            yield res
                    else:
                        raise Exception("add")
                elif node.name == "map":
                    if isinstance(input_val, list):
                        if not node.args:
                            raise Exception("map")
                        map_filter = node.args[0]
                        result = []
                        for el in input_val:
                            for out in eval_filter(map_filter, el, ctx):
                                result.append(out)
                        yield result
                    else:
                        raise Exception("map")
                elif node.name == "select":
                    if not node.args:
                        raise Exception("select")
                    cond_filter = node.args[0]
                    cond_vals = list(eval_filter(cond_filter, input_val, ctx))
                    for cv in cond_vals:
                        if cv is not False and cv is not None:
                            yield input_val
