                    yield json.dumps(input_val, ensure_ascii=False)
                elif node.name == "fromjson":
                    if isinstance(input_val, str):
                        yield json.loads(input_val)
                    else:
                        raise Exception("fromjson")
                elif node.name == "split":
                    if isinstance(input_val, str):
                        sep = evaluated_args[0] if evaluated_args else ""
                        yield input_val.split(sep)
                    else:
                        raise Exception("split")
                elif node.name == "join":
                    if isinstance(input_val, list):
                        sep = evaluated_args[0] if evaluated_args else ""
                        yield sep.join(str(x) for x in input_val)
                    else:
                        raise Exception("join")
                elif node.name == "contains":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
