                elif node.name == "endswith":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        yield input_val.endswith(evaluated_args[0])
                    else:
                        yield False
                elif node.name == "ltrimstr":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        s = evaluated_args[0]
                        if input_val.startswith(s):
                            yield input_val[len(s):]
                        else:
                            yield input_val
                    else:
                        raise Exception("ltrimstr")
                elif node.name == "rtrimstr":
                    if isinstance(input_val, str) and isinstance(evaluated_args[0], str):
                        s = evaluated_args[0]
                        if input_val.endswith(s):
                            yield input_val[:-len(s)] if s != "" else input_val
                        else:
                            yield input_val
                    else:
                        raise Exception("rtrimstr")
                elif node.name == "sort":
                    if isinstance(input_val, list):
                        try:
                            yield sorted(input_val)
                        except:
                            yield sorted(input_val, key=lambda x: str(x))
                    else:
                        raise Exception("sort")
                elif node.name == "unique":
                    if isinstance(input_val, list):
                        try:
                            yield sorted(set(input_val))
                        except:
                            seen = []
                            for x in input_val:
                                if x not in seen:
                                    seen.append(x)
                            yield seen
                    else:
                        raise Exception("unique")
                elif node.name == "reverse":
                    if isinstance(input_val, list):
                        yield list(reversed(input_val))
                    else:
                        raise Exception("reverse")
                elif node.name == "flatten":
                    if isinstance(input_val, list):
                        depth = evaluated_args[0] if evaluated_args else None
                        def flatten(arr, d):
                            res = []
                            for el in arr:
                                if isinstance(el, list) and (d is None or d>0):
                                    nd = None if d is None else d-1
                                    res.extend(flatten(el, nd))
                                else:
                                    res.append(el)
                            return res
                        yield flatten(input_val, depth)
                    else:
                        raise Exception("flatten")
                elif node.name == "any":
                    if isinstance(input_val, list):
                        yield any(el is not False and el is not None for el in input_val)
                    else:
                        raise Exception("any")
                elif node.name == "all":
                    if isinstance(input_val, list):
                        yield all(el is not False and el is not None for el in input_val)
                    else:
                        raise Exception("all")
                elif node.name == "first":
                    if isinstance(input_val, list):
                        if len(input_val)>0:
                            yield input_val[0]
                elif node.name == "last":
                    if isinstance(input_val, list):
                        if len(input_val)>0:
                            yield input_val[-1]
                elif node.name == "nth":
                    n = evaluated_args[0] if evaluated_args else 0
                    if isinstance(input_val, list):
                        if 0 <= n < len(input_val):
                            yield input_val[n]
                        elif n < 0 and -len(input_val) <= n:
                            yield input_val[n]
                elif node.name == "limit":
                    if len(node.args) >= 2:
                        n_filter = node.args[0]
                        inner_filter = node.args[1]
                        n_vals = list(eval_filter(n_filter, input_val, ctx))
                        n_val = n_vals[0] if n_vals else 0
                        count = 0
                        for out in eval_filter(inner_filter, input_val, ctx):
                            if count < n_val:
                                yield out
                                count+=1
                            else:
                                break
