        try:
            yield from eval_filter(node.try_branch, input_val, ctx)
        except Exception as e:
            if node.catch_branch is not None:
                yield from eval_filter(node.catch_branch, str(e), ctx)
            else:
                yield None
    elif isinstance(node, DefNode):
        new_ctx = ctx.copy()
        new_ctx.funcs[node.name] = (node.params, node.body)
        yield from eval_filter(node.next_filter, input_val, new_ctx)
    else:
        raise Exception(f"Unsupported node {type(node)}")

def main():
    argv = sys.argv[1:]
    opts, positional = parse_cli_v2(argv)
    filter_str, input_files, mode_positional = determine_filter_and_files(opts, positional)

    named_vars = {}
    for name, val in opts["arg_vars"]:
        if name not in named_vars:
            named_vars[name] = val
    for name, val in opts["argjson_vars"]:
        if name not in named_vars:
            try:
                parsed = json.loads(val)
            except:
                exit_error(f"jq: invalid JSON text passed to --argjson\n{HELP_FOOTER}",2)
            named_vars[name] = parsed
    for name, fname in opts["slurpfile_vars"]:
        if name not in named_vars:
            try:
                with open(fname, 'r', encoding='utf-8') as f:
                    data = f.read()
                    vals = parse_json_values(data)
                    named_vars[name] = vals
            except FileNotFoundError:
                exit_error(f"jq: Bad JSON in --slurpfile {name} {fname}: Could not open {fname}: No such file or directory\n",2)
            except Exception as e:
                exit_error(f"jq: Bad JSON in --slurpfile {name} {fname}: {e}\n",2)
    for name, fname in opts["rawfile_vars"]:
        if name not in named_vars:
            try:
                with open(fname, 'r', encoding='utf-8') as f:
                    data = f.read()
                    named_vars[name] = data
            except FileNotFoundError:
                exit_error(f"jq: Bad JSON in --rawfile {name} {fname}: Could not open {fname}: No such file or directory\n",2)

    positional_args = []
    if opts["args_mode"] == "args":
        positional_args = mode_positional
    elif opts["args_mode"] == "jsonargs":
        for p in mode_positional:
            try:
                parsed = json.loads(p)
                positional_args.append(parsed)
            except:
                exit_error(f"jq: invalid JSON text passed to --jsonargs\n{HELP_FOOTER}",2)

    args_obj = {
        "positional": positional_args,
        "named": named_vars
    }

    ctx = JQContext()
    ctx.vars.update(named_vars)
    ctx.vars["ARGS"] = args_obj

    # Library path include check
    if "include" in filter_str or "import" in filter_str:
        import re
        m = re.search(r'include\s+"([^"]+)"', filter_str)
        if m:
            mod = m.group(1)
            found = False
            for lp in opts["library_paths"]:
                p1 = os.path.join(lp, mod + ".jq")
                p2 = os.path.join(lp, mod)
                if os.path.isfile(p1) or os.path.isfile(p2):
                    found = True
                    break
            if not found:
                eprint(f"jq: error: module not found: {mod}\n\njq: 1 compile error\n")
                sys.exit(3)

    def read_all_remaining():
        tmp_opts = dict(opts)
        tmp_opts["null_input"] = False
        try:
            return read_inputs(tmp_opts, input_files)
        except:
            return []

    try:
        main_inputs = read_inputs(opts, input_files)
    except json.JSONDecodeError as e:
        eprint(f"jq: parse error: {e.msg} at line {e.lineno}, column {e.colno}\n")
        sys.exit(5)
    except Exception as e:
        eprint(f"jq: {e}\n")
        sys.exit(5)

    if opts["null_input"]:
        try:
            remaining_inputs = read_all_remaining()
        except:
            remaining_inputs = []
        ctx.vars["_inputs_remaining"] = remaining_inputs
        ctx.vars["_inputs_index"] = 0
    else:
        pass

    try:
        tokens = tokenize(filter_str)
        parser = Parser(tokens, filter_str)
        ast_root = parser.parse()
    except SyntaxError as se:
        msg = str(se)
        if "Top-level" in msg:
            eprint(f"jq: error: {msg}\njq: 1 compile error\n")
            sys.exit(3)
        eprint(f"jq: error: {msg} at <top-level>, line 1, column 1:\n    {filter_str}\n    ^\njq: 1 compile error\n")
        sys.exit(3)
    except Exception as e:
        eprint(f"jq: error: {e} at <top-level>, line 1, column 1:\n    {filter_str}\n    ^\njq: 1 compile error\n")
        sys.exit(3)

    all_outputs = []
    try:
        if opts["null_input"]:
            for out_val in eval_filter(ast_root, None, ctx):
                all_outputs.append(out_val)
        else:
            for idx, inp_val in enumerate(main_inputs):
                remaining = main_inputs[idx+1:]
                ctx.vars["_inputs_remaining"] = remaining
                ctx.vars["_inputs_index"] = 0
                for out_val in eval_filter(ast_root, inp_val, ctx):
                    all_outputs.append(out_val)
    except Exception as e:
        err_msg = str(e)
        if "is not defined" in err_msg:
            eprint(f"jq: error: {err_msg} at <top-level>, line 1, column 1:\n    {filter_str}\n    ^\njq: 1 compile error\n")
            sys.exit(3)
        else:
            eprint(f"jq: error (at <unknown>): {err_msg}\n")
            sys.exit(5)

    if opts["exit_status"]:
        if len(all_outputs) == 0:
            exit_code = 4
        else:
            last = all_outputs[-1]
            if last is False or last is None:
                exit_code = 1
            else:
                exit_code = 0
    else:
        exit_code = 0

    indent_val = opts["indent"]
    if indent_val is None:
        if opts["tab"]:
            indent_val = -1
        else:
            indent_val = 2

    compact = opts["compact"]
    color = opts["color_output"] and not opts["monochrome_output"]
    raw = opts["raw_output"]
    raw0 = opts["raw_output0"]
    join = opts["join_output"]
    ascii_out = opts["ascii_output"]
    sort_keys = opts["sort_keys"]
    seq_out = opts["seq"]

    if raw0:
        terminator = "\0"
    elif join:
        terminator = ""
    else:
        terminator = "\n"

    out_fh = sys.stdout
    for out_val in all_outputs:
        is_string = isinstance(out_val, str)
        if is_string and raw:
            if ascii_out:
                json_str = json.dumps(out_val, ensure_ascii=True)
                if seq_out:
                    out_fh.write(json_str + terminator)
                else:
                    out_fh.write(json_str + terminator)
            else:
                if seq_out:
                    out_fh.write(out_val + terminator)
                else:
                    out_fh.write(out_val + terminator)
        else:
            if compact:
                json_str = json_dumps_compact(out_val, sort_keys=sort_keys, ascii_output=ascii_out, color=color)
            else:
                if indent_val == -1:
                    json_str = json_dumps_pretty(out_val, sort_keys=sort_keys, ascii_output=ascii_out, indent_spaces=1, use_tab=True, color=color, current_level=0)
                else:
                    json_str = json_dumps_pretty(out_val, sort_keys=sort_keys, ascii_output=ascii_out, indent_spaces=indent_val, use_tab=False, color=color, current_level=0)
            if seq_out:
                if is_string and raw:
                    out_fh.write(json_str + terminator)
                else:
                    out_fh.write("\x1e" + json_str + terminator)
            else:
                out_fh.write(json_str + terminator)
        if opts["unbuffered"]:
            out_fh.flush()

    sys.exit(exit_code)

if __name__ == "__main__":
    main()
