import re, json
def tokenize(s):
    pos=0
    tokens=[]
    n=len(s)
    while pos<n:
        m=re.match(r'\s+', s[pos:])
        if m:
            pos+=len(m.group(0))
            continue
        if s[pos]=='"':
            end=pos+1
            while end<n:
                if s[end]=='\\':
                    end+=2
                elif s[end]=='"':
                    end+=1
                    break
                else:
                    end+=1
            tokens.append(('STRING', s[pos:end], pos))
            pos=end
            continue
        m=re.match(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?', s[pos:])
        if m and m.group(0) not in ('','-'):
            tokens.append(('NUMBER', m.group(0), pos))
            pos+=len(m.group(0))
            continue
        if s[pos:pos+2]=='..':
            tokens.append(('DOTDOT','..',pos))
            pos+=2
            continue
        if s[pos]=='.':
            tokens.append(('DOT','.',pos))
            pos+=1
            continue
        if s[pos]=='$':
            tokens.append(('DOLLAR','$',pos))
            pos+=1
            continue
        if s[pos]=='|':
            tokens.append(('PIPE','|',pos))
            pos+=1
            continue
        if s[pos]==',':
            tokens.append(('COMMA',',',pos))
            pos+=1
            continue
        if s[pos]==';':
            tokens.append(('SEMICOLON',';',pos))
            pos+=1
            continue
        if s[pos]==':':
            tokens.append(('COLON',':',pos))
            pos+=1
            continue
        if s[pos]=='(':
            tokens.append(('LPAREN','(',pos))
            pos+=1
            continue
        if s[pos]==')':
            tokens.append(('RPAREN',')',pos))
            pos+=1
